using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Reflection;
using Newtonsoft.Json;

namespace AzeronHud.Layout;

/// <summary>
/// Where each button sits on the keypad, as a cell in the same CSS grid the
/// Azeron configurator lays its mapper out with. Generated by
/// tools/extract_layout.py and embedded, so the plugin needs nothing from the
/// Azeron AppImage at runtime.
/// </summary>
internal sealed class DeviceLayout
{
    [JsonProperty("name")] public string Name = string.Empty;

    /// <summary>KeypadType, matching a profile's metaData.device.</summary>
    [JsonProperty("keypadType")] public int KeypadType;

    /// <summary>USB product ID, which is also the DevicesStorage directory name.</summary>
    [JsonProperty("productId")] public int ProductId;

    [JsonProperty("columns")] public int Columns;
    [JsonProperty("rows")] public int Rows;

    /// <summary>Cell height as a multiple of cell width (the configurator uses 106/75).</summary>
    [JsonProperty("cellAspect")] public float CellAspect = 1f;

    [JsonProperty("buttons")] public List<LayoutButton> Buttons = new();

    private static Dictionary<int, DeviceLayout>? byProductId;

    /// <summary>All embedded layouts, keyed by USB product ID.</summary>
    internal static IReadOnlyDictionary<int, DeviceLayout> All => byProductId ??= LoadEmbedded();

    internal static DeviceLayout? ForProductId(int productId) =>
        All.TryGetValue(productId, out var l) ? l : null;

    /// <summary>
    /// Pixel rect for a button, given the cell width and the gap between cells.
    /// Mirrors the configurator: cells are uniform, spans cover the gaps they
    /// straddle.
    /// </summary>
    internal (Vector2 Pos, Vector2 Size) Rect(LayoutButton b, float cellWidth, float gap)
    {
        var cellHeight = cellWidth * CellAspect;
        var pos = new Vector2(b.Col * (cellWidth + gap), b.Row * (cellHeight + gap));
        var size = new Vector2(
            (b.ColSpan * cellWidth) + ((b.ColSpan - 1) * gap),
            (b.RowSpan * cellHeight) + ((b.RowSpan - 1) * gap));
        return (pos, size);
    }

    /// <summary>Total pixel size of the whole grid at this cell width.</summary>
    internal Vector2 GridSize(float cellWidth, float gap)
    {
        var cellHeight = cellWidth * CellAspect;
        return new Vector2(
            (Columns * cellWidth) + ((Columns - 1) * gap),
            (Rows * cellHeight) + ((Rows - 1) * gap));
    }

    private static Dictionary<int, DeviceLayout> LoadEmbedded()
    {
        var result = new Dictionary<int, DeviceLayout>();
        var asm = Assembly.GetExecutingAssembly();

        foreach (var name in asm.GetManifestResourceNames().Where(n => n.EndsWith(".json", StringComparison.Ordinal)))
        {
            using var stream = asm.GetManifestResourceStream(name);
            if (stream == null)
                continue;

            using var reader = new StreamReader(stream);
            var layout = JsonConvert.DeserializeObject<DeviceLayout>(reader.ReadToEnd());
            if (layout is { ProductId: > 0 })
                result[layout.ProductId] = layout;
        }

        return result;
    }
}

internal sealed class LayoutButton
{
    /// <summary>Matches an Azeron profile input's <c>id</c>.</summary>
    [JsonProperty("id")] public int Id;

    [JsonProperty("col")] public int Col;
    [JsonProperty("row")] public int Row;
    [JsonProperty("colSpan")] public int ColSpan = 1;
    [JsonProperty("rowSpan")] public int RowSpan = 1;
}
